/* Mercator simple, encuadrado en un ancho × alto con margen. Devuelve la
   función que proyecta [lon, lat] → [x, y] y el trazo del contorno. */
const merc = (lat) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
export function proyeccion(ancho, alto, margen = 8) {
  const xs = CONTORNO.map((p) => p[0]), ys = CONTORNO.map((p) => merc(p[1]));
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  const k = Math.min((ancho - 2 * margen) / ((x1 - x0) * Math.PI / 180), (alto - 2 * margen) / (y1 - y0));
  const dx = (ancho - k * (x1 - x0) * Math.PI / 180) / 2, dy = (alto - k * (y1 - y0)) / 2;
  const p = (lon, lat) => [dx + k * (lon - x0) * Math.PI / 180, dy + k * (y1 - merc(lat))];
  const trazo = 'M' + CONTORNO.map(([lon, lat]) => p(lon, lat).map((v) => v.toFixed(1)).join(',')).join('L') + 'Z';
  return { p, trazo };
}
